INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15701, 'តាមនិយមន័យ បន្ទាត់ពីរស្របគ្នាក្នុងលំហ គឺជាបន្ទាត់ពីរដែល ៖', NULL, '["នៅក្នុងប្លង់តែមួយ ហើយគ្មានចំណុចរួម", "កាត់គ្នាក្នុងលំហ", "មានចំណុចរួមមួយគត់", "មិននៅក្នុងប្លង់តែមួយ ហើយគ្មានចំណុចរួម"]', 0, NULL, 1, 'mcq', 'បន្ទាត់ពីរស្របគ្នាជាបន្ទាត់ស្ថិតក្នុងប្លង់តែមួយ និងគ្មានចំណុចរួម d1 // d2 <=> d1, d2 ⊂ (P) និង d1 ∩ d2 = ∅។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15702, 'តាមចំណុចមួយ \(A\) នៅក្រៅបន្ទាត់ \(d\) គេអាចគូសបន្ទាត់ស្របនឹង \(d\) បានចំនួនប៉ុន្មាន?', NULL, '["តែមួយគត់", "បានច្រើនរាប់មិនអស់", "បានបី", "បានពីរ"]', 0, NULL, 1, 'mcq', 'តាមស្វ័យសត្យបន្ទាត់ស្រប តាមមួយចំណុចក្រៅបន្ទាត់ គេអាចគូសបន្ទាត់ស្របបានតែមួយគត់។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15703, 'បន្ទាត់មួយស្របនឹងប្លង់មួយ កាលណា ៖', NULL, '["បន្ទាត់កាត់ប្លង់ត្រង់មួយចំណុច", "បន្ទាត់និងប្លង់គ្មានចំណុចរួមសោះ", "បន្ទាត់ស្ថិតនៅក្នុងប្លង់ទាំងមូល", "បន្ទាត់កែងនឹងប្លង់"]', 1, NULL, 1, 'mcq', 'បន្ទាត់ស្របនឹងប្លង់កាលណា d ∩ (P) = ∅។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15704, 'ប្លង់ពីរស្របគ្នា កាលណាពួកវា ៖', NULL, '["មានចំណុចរួមមួយគត់", "គ្មានចំណុចរួមសោះ", "កែងគ្នា", "កាត់គ្នាតាមបន្ទាត់មួយ"]', 1, NULL, 1, 'mcq', 'ប្លង់ពីរស្របគ្នា <=> (P) ∩ (Q) = ∅។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15705, 'ប្លង់ស្របគ្នាបីកាត់ខ្នាត់ពីរ \(\Delta\) និង \(\Delta''\) ត្រង់ \(A, B, C\) និង \(A'', B'', C''\)។ តាមទ្រឹស្តីបទតាលែស ផលធៀបណាត្រឹមត្រូវ?', NULL, '["\\(\\frac{A''B''}{AB} = \\frac{B''C''}{BC}\\)", "\\(\\frac{A''B''}{BC} = \\frac{B''C''}{AB}\\)", "\\(\\frac{A''B''}{A''C''} = \\frac{BC}{AB}\\)", "\\(A''B'' \\times AB = B''C'' \\times BC\\)"]', 0, NULL, 1, 'mcq', 'ទ្រឹស្តីបទតាលែសក្នុងលំហ A''B''/AB = B''C''/BC = A''C''/AC។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15706, 'បើ \(d_1 \parallel d_2\) ហើយ \(d_2 \parallel d_3\) នោះទំនាក់ទំនងរវាង \(d_1\) និង \(d_3\) គឺ ៖', NULL, '["\\(d_1 \\cap d_3 \neq \\emptyset\\)", "\\(d_1 \text{ និង } d_3 \text{ ជាបន្ទាត់ទ្វេរ}\\)", "\\(d_1 \\perp d_3\\)", "\\(d_1 \\parallel d_3\\)"]', 3, NULL, 1, 'mcq', 'ភាពស្របគ្នានៃបន្ទាត់ក្នុងលំហមានលក្ខណៈឆ្លង d1 // d2 និង d2 // d3 => d1 // d3។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15707, 'បើបន្ទាត់ \(d\) នៅក្រៅប្លង់ \((P)\) ហើយស្របនឹងបន្ទាត់ \(d'' \subset (P)\) នោះ ៖', NULL, '["\\(d \\subset (P)\\)", "\\(d \\cap (P) = \\{O\\}\\)", "\\(d \\perp (P)\\)", "\\(d \\parallel (P)\\)"]', 3, NULL, 1, 'mcq', 'លក្ខខណ្ឌបន្ទាត់ស្របនឹងប្លង់ ៖ បើបន្ទាត់មួយក្រៅប្លង់ស្របនឹងបន្ទាត់មួយក្នុងប្លង់ នោះវាស្របនឹងប្លង់នោះ។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15708, 'តាមចំណុចមួយនៅក្រៅប្លង់ \((P)\) គេអាចគូសប្លង់ស្របនឹង \((P)\) បានចំនួនប៉ុន្មាន?', NULL, '["រាប់មិនអស់", "បានបី", "តែមួយគត់", "បានពីរ"]', 2, NULL, 1, 'mcq', 'តាមមួយចំណុចនៅក្រៅប្លង់ គេអាចគូសបានប្លង់ស្របតែមួយគត់។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15709, 'បើ \((P) \parallel (Q)\) ហើយ \((S) \parallel (Q)\) នោះ ៖', NULL, '["\\((P) \\equiv (Q)\\)", "\\((P) \\perp (S)\\)", "\\((P) \\parallel (S)\\)", "\\((P) \\cap (S) = \\Delta\\)"]', 2, NULL, 1, 'mcq', 'ភាពស្របគ្នានៃប្លង់មានលក្ខណៈឆ្លង (P) // (Q) និង (S) // (Q) => (P) // (S)។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15710, 'ក្នុងគូប \(ABCD.EFGH\) ប្លង់ពិដាន \((EFGH)\) ស្របនឹងប្លង់ណា?', NULL, '["\\((CDHG)\\)", "\\((ABFE)\\)", "\\((BCGF)\\)", "\\((ABCD)\\)"]', 3, NULL, 1, 'mcq', 'ក្នុងគូប មុខឈមទាំងពីរស្របគ្នា ដូច្នេះប្លង់ពិដាន (EFGH) ស្របនឹងប្លង់បាត (ABCD)។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15711, 'បើបន្ទាត់ពីរស្របគ្នា \(d \parallel d''\) ហើយប្លង់ \((P)\) កាត់ \(d\) ត្រង់ \(A\) នោះប្លង់ \((P)\) នឹង ៖', NULL, '["មិនកាត់បន្ទាត់ d'' ទេ", "ស្របនឹងបន្ទាត់ d''", "កាត់បន្ទាត់ d'' ត្រង់ចំណុច B មួយដែរ", "ផ្ទុកបន្ទាត់ d'' ទាំងមូល"]', 2, NULL, 2, 'mcq', 'បើបន្ទាត់ពីរស្របគ្នា គ្រប់ប្លង់ដែលកាត់បន្ទាត់ទី ១ ត្រូវតែកាត់បន្ទាត់ទី ២។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15712, 'បើបន្ទាត់ \(d \parallel (P)\) ហើយប្លង់ \((Q)\) ផ្ទុក \(d\) ប្រសព្វនឹង \((P)\) តាមបន្ទាត់ \(d''\) នោះ ៖', NULL, '["\\(d \\perp d''\\)", "\\(d \\cap d'' = \\{O\\}\\)", "\\(d \\parallel d''\\)", "\\(d \\equiv d''\\)"]', 2, NULL, 2, 'mcq', 'តាមលក្ខណៈប្លង់កាត់តាមបន្ទាត់ស្រប បន្ទាត់ប្រសព្វ d'' ត្រូវតែស្របនឹង d។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15713, 'ប្លង់ពីរស្របគ្នា \((P) \parallel (Q)\) ត្រូវបានកាត់ដោយប្លង់ទី ៣ \((R)\) តាមបន្ទាត់ប្រសព្វ \(d_1\) និង \(d_2\)។ នោះ ៖', NULL, '["\\(d_1 \\parallel d_2\\)", "\\(d_1 \\cap d_2 = \\{A\\}\\)", "\\(d_1 \\perp d_2\\)", "\\(d_1 \text{ និង } d_2 \text{ ជាបន្ទាត់ទ្វេរ}\\)"]', 0, NULL, 2, 'mcq', 'ប្លង់ពីរស្របគ្នាកាត់ដោយប្លង់ទី ៣ នោះបន្ទាត់ប្រសព្វទាំងពីរស្របគ្នាជានិច្ច។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15714, 'ក្នុងពីរ៉ាមីត \(S.ABCD\) ដែលបាត \(ABCD\) ជាការេ។ ប្លង់មួយកាត់តាម \(BC\) ប្រសព្វមុខ \((SAD)\) តាម \(IJ\)។ ចតុកោណ \(BCJI\) ជា ៖', NULL, '["ចតុកោណកែង", "ចតុកោណព្នាយ", "ការេ", "ប្រលេឡូក្រាម"]', 1, NULL, 2, 'mcq', 'BC // AD នាំឱ្យ BC // (SAD) ដូច្នេះប្រសព្វ IJ // BC នាំឱ្យ BCJI ជាចតុកោណព្នាយ។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15715, 'ក្នុងចតុមុខ \(ABCD\) តាង \(I, J, K, L\) ជាចំណុចកណ្តាលនៃ \(AB, BC, CD, DA\)។ ចតុកោណ \(IJKL\) ជា ៖', NULL, '["ចតុកោណព្នាយ", "ចតុកោណកែង", "ប្រលេឡូក្រាម", "ចតុកោណស្មើ"]', 2, NULL, 2, 'mcq', 'តាមទ្រឹស្តីបទបាតមធ្យម IJ // LK // AC និង IL // JK // BD នាំឱ្យ IJKL ជាប្រលេឡូក្រាម។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15716, 'ប្លង់ស្របគ្នាបីកាត់ខ្នាត់ \(\Delta\) ត្រង់ \(A, B, C\) និងខ្នាត់ \(\Delta''\) ត្រង់ \(A'', B'', C''\)។ បើ \(AB = 4	ext{ cm}, BC = 6	ext{ cm}\) និង \(A''B'' = 6	ext{ cm}\) នោះប្រវែង \(B''C''\) គឺ ៖', NULL, '["\\(9\text{ cm}\\)", "\\(12\text{ cm}\\)", "\\(8\text{ cm}\\)", "\\(10\text{ cm}\\)"]', 0, NULL, 2, 'mcq', 'តាមតាលែស B''C'' = (BC x A''B'') / AB = (6 x 6) / 4 = 9 cm។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15717, 'គេមានបន្ទាត់ \(a \parallel b\) ដោយ \(a \subset (P)\) និង \(b \subset (Q)\) ហើយ \((P) \cap (Q) = l\)។ នោះ ៖', NULL, '["\\(l \text{ និង } a \text{ ជាបន្ទាត់ទ្វេរ}\\)", "\\(l \\parallel a \text{ និង } l \\parallel b\\)", "\\(l \\perp a\\)", "\\(l \text{ កាត់ } a\\)"]', 1, NULL, 2, 'mcq', 'បន្ទាត់ប្រសព្វនៃប្លង់ពីរកាត់តាមបន្ទាត់ស្របពីរ ត្រូវតែស្របនឹងបន្ទាត់ទាំងពីរនោះ។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15718, 'បើបន្ទាត់ \(d\) មួយស្របនឹងប្លង់ពីរប្រសព្វគ្នា \((P)\) និង \((Q)\) ដែល \((P) \cap (Q) = \Delta\) នោះ ៖', NULL, '["\\(d \\parallel \\Delta\\)", "\\(d \\cap \\Delta = \\{A\\}\\)", "\\(d \\subset (P)\\)", "\\(d \\perp \\Delta\\)"]', 0, NULL, 2, 'mcq', 'បន្ទាត់មួយស្របនឹងប្លង់ពីរប្រសព្វគ្នា នោះវាស្របនឹងបន្ទាត់ប្រសព្វនៃប្លង់ទាំងពីរ។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15719, 'គេឱ្យ \((P) \parallel (Q)\) និងបន្ទាត់ស្របពីរ \(d_1 \parallel d_2\) កាត់ប្លង់ទាំងពីរត្រង់ \(A, B\) និង \(C, D\)។ ប្រភេទចតុកោណ \(ABCD\) គឺ ៖', NULL, '["ចតុកោណកែង", "ប្រលេឡូក្រាម", "ចតុកោណព្នាយ", "ចតុកោណស្មើ"]', 1, NULL, 2, 'mcq', 'ចតុកោណ ABCD មានជ្រុងឈមស្របគ្នារៀងៗខ្លួន (AB // CD និង AC // BD) ដូច្នេះជាប្រលេឡូក្រាម។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15720, 'ក្នុងចតុមុខ \(OABC\) ចំណុច \(M, N, P\) ជាចំណុចកណ្តាលនៃ \(OA, OB, OC\)។ ផលធៀបផ្ទៃក្រឡា \(\frac{S_{MNP}}{S_{ABC}}\) គឺ ៖', NULL, '["\\(\\frac{1}{2}\\)", "\\(\\frac{1}{3}\\)", "\\(\\frac{1}{4}\\)", "\\(\\frac{1}{8}\\)"]', 2, NULL, 2, 'mcq', 'ត្រីកោណ MNP ដូចគ្នាត្រីកោណ ABC តាមផលធៀបកម្សោយ k = 1/2 នាំឱ្យផលធៀបផ្ទៃ k^2 = 1/4។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15721, 'ប្លង់ស្របគ្នាបីកាត់ខ្នាត់ពីរបាន \(AB = 3, BC = 5\) និង \(A''C'' = 16\)។ ប្រវែង \(A''B''\) គឺ ៖', NULL, '["\\(6\\)", "\\(8\\)", "\\(10\\)", "\\(4.5\\)"]', 0, NULL, 2, 'mcq', 'AC = 3 + 5 = 8; A''B'' = (AB x A''C'') / AC = (3 x 16) / 8 = 6។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15722, 'ក្នុងគូប \(ABCD.EFGH\) បន្ទាត់ \(AB\) ស្របនឹងប្លង់ណាខាងក្រោម?', NULL, '["\\((ABFE)\\)", "\\((CDHG)\\)", "\\((ADHE)\\)", "\\((ABCD)\\)"]', 1, NULL, 2, 'mcq', 'AB // CD ហើយ CD ⊂ (CDHG) និង AB ⊄ (CDHG) នាំឱ្យ AB // (CDHG)។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15723, 'អង្កត់នៃបន្ទាត់ស្របពីរដែលខណ្ឌដោយប្លង់ស្របគ្នាពីរ មានប្រវែង ៖', NULL, '["មិនអាចប្រៀបធៀបបាន", "ខុសគ្នាជានិច្ច", "មួយធំជាងមួយពីរដង", "ស្មើគ្នាជានិច្ច"]', 3, NULL, 2, 'mcq', 'ដោយចតុកោណដែលបង្កើតឡើងជាប្រលេឡូក្រាម ជ្រុងឈម AC = BD ស្មើគ្នា។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15724, 'ក្នុងគូប \(ABCD.EFGH\) ប្លង់ \((ACH)\) ស្របនឹងប្លង់ណា?', NULL, '["\\((ABCD)\\)", "\\((BDF)\\)", "\\((EFGH)\\)", "\\((EGB)\\)"]', 3, NULL, 2, 'mcq', 'AC // EG, CH // EB, AH // GB នាំឱ្យប្លង់ (ACH) // ប្លង់ (EGB)។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15725, 'គេឱ្យតេត្រាអែត \(ABCD\)។ បន្ទាត់ \(d\) កាត់តាម \(A\) ស្របនឹង \(BC\) ហើយ \(d''\) កាត់តាម \(D\) ស្របនឹង \(AB\)។ ទំនាក់ទំនងរវាង \(d\) និង \(d''\) គឺ ៖', NULL, '["កាត់គ្នា", "ជាបន្ទាត់ទ្វេរ (មិនស្ថិតក្នុងប្លង់តែមួយ)", "ត្រួតស៊ីគ្នា", "ស្របគ្នា"]', 1, NULL, 3, 'mcq', 'បើ d និង d'' ក្នុងប្លង់តែមួយ នាំឱ្យ C ∈ (ABD) ផ្ទុយនឹងនិយមន័យតេត្រាអែត។ ដូច្នេះជាបន្ទាត់ទ្វេរ។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'hard', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15726, 'ប្លង់ស្របគ្នាបីកាត់ខ្នាត់ \(\Delta\) ត្រង់ \(A, B, C\) និង \(\Delta''\) ត្រង់ \(A'', B'', C''\)។ បើ \(\frac{AB}{BC} = \frac{2}{3}\) និង \(A''C'' = 25	ext{ cm}\) នោះ \(B''C''\) ស្មើ ៖', NULL, '["\\(15\text{ cm}\\)", "\\(18\text{ cm}\\)", "\\(10\text{ cm}\\)", "\\(12\text{ cm}\\)"]', 0, NULL, 3, 'mcq', 'B''C'' = 25 x (3 / (2 + 3)) = 25 x 3/5 = 15 cm។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'hard', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15727, 'ពីរ៉ាមីត \(S.ABC\) ត្រូវបានកាត់ដោយប្លង់ \((P)\) ស្របនឹងបាត \((ABC)\) ត្រង់ចំណុចកណ្តាលនៃកម្ពស់ \(SO\)។ ផលធៀបមាឌពីរ៉ាមីតតូចលើពីរ៉ាមីតធំគឺ ៖', NULL, '["\\(\\frac{1}{4}\\)", "\\(\\frac{1}{8}\\)", "\\(\\frac{1}{16}\\)", "\\(\\frac{1}{2}\\)"]', 1, NULL, 3, 'mcq', 'ផលធៀបទ្រនុង k = 1/2 នាំឱ្យផលធៀបមាឌគឺ k^3 = (1/2)^3 = 1/8។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'hard', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15728, 'ក្នុងចតុមុខ \(ABCD\) ដែល \(AC = 8	ext{ cm}\) និង \(BD = 6	ext{ cm}\)។ បរិមាត្រនៃប្រលេឡូក្រាម \(IJKL\) បង្កើតដោយចំណុចកណ្តាលទ្រនុងទាំងបួនគឺ ៖', NULL, '["\\(28\text{ cm}\\)", "\\(12\text{ cm}\\)", "\\(24\text{ cm}\\)", "\\(14\text{ cm}\\)"]', 3, NULL, 3, 'mcq', 'IJ = LK = AC/2 = 4 cm; IL = JK = BD/2 = 3 cm; បរិមាត្រ = 2(4 + 3) = 14 cm។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'hard', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15729, 'គេឱ្យបន្ទាត់ \(a\) និង \(d\) ស្របគ្នាក្នុងប្លង់ \((P)\)។ ប្លង់ \((Q)\) កាត់តាម \(a, b\) និងប្លង់ \((Q'')\) កាត់តាម \(d, b\)។ នោះ ៖', NULL, '["\\(b \\subset (P)\\)", "\\(b \text{ កាត់ } (P)\\)", "\\(b \\perp (P)\\)", "\\(b \\parallel (P)\\)"]', 3, NULL, 3, 'mcq', 'បន្ទាត់ b ជាប្រសព្វនៃ (Q) និង (Q'') នាំឱ្យ b // a // d ដូច្នេះ b // (P)។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'hard', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15730, 'ចតុមុខ \(ABCD\) មាន \(M \in AB\) ដោយ \(AM = 2MB\)។ ប្លង់កាត់តាម \(M\) ស្របនឹង \((BCD)\) កាត់ \(AC, AD\) ត្រង់ \(N, P\)។ ផលធៀប \(\frac{S_{MNP}}{S_{BCD}}\) គឺ ៖', NULL, '["\\(\\frac{1}{9}\\)", "\\(\\frac{1}{3}\\)", "\\(\\frac{2}{3}\\)", "\\(\\frac{4}{9}\\)"]', 3, NULL, 3, 'mcq', 'AM/AB = 2/3 នាំឱ្យផលធៀបផ្ទៃនៃត្រីកោណដូចគ្នាគឺ (2/3)^2 = 4/9។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'hard', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15731, 'ក្នុងគូប \(ABCD.EFGH\) តាង \(I, J\) ជាចំណុចកណ្តាលនៃ \(AB, BC\)។ ប្លង់ \((EIJ)\) កាត់គូបបានមុខកាត់ជារាង ៖', NULL, '["ចតុកោណព្នាយសមបាត", "ចតុកោណកែង", "ត្រីកោណសមបាត", "ប្រលេឡូក្រាម"]', 0, NULL, 3, 'mcq', 'មុខកាត់កាត់តាម IJ // AC និងកាត់មុខខាងលើតាមបន្ទាត់ស្របនឹង AC នាំឱ្យបានចតុកោណព្នាយសមបាត។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'hard', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15732, 'កាំជណ្ដើរឈើមួយមានកាំនីមួយៗស្របគ្នា និងស្របនឹងកម្រាលឥដ្ឋ។ តាមទស្សនៈធរណីមាត្រលំហ កាំជណ្ដើរទាំងអស់ ៖', NULL, '["មិនមានទំនាក់ទំនងនឹងកម្រាលឥដ្ឋ", "កែងនឹងប្លង់កម្រាលឥដ្ឋ", "កាត់ប្លង់កម្រាលឥដ្ឋ", "ស្របនឹងប្លង់កម្រាលឥដ្ឋជានិច្ច"]', 3, NULL, 3, 'mcq', 'បន្ទាត់ដែលស្របនឹងបន្ទាត់ក្នុងប្លង់កម្រាលឥដ្ឋ តែងតែស្របនឹងប្លង់កម្រាលឥដ្ឋ។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'pisa', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15733, 'អគារពាណិជ្ជកម្មកម្ពស់ ៥ ជាន់ មានកម្រាលពិដាននៃជាន់នីមួយៗស្របគ្នា។ ប្រសិនបើគេដំឡើងខ្សែខ្សែកាបអុបទិកត្រង់មួយកាត់តាមគ្រប់ជាន់ ចម្ងាយរវាងជាន់នីមួយៗវាស់តាមខ្សែនោះ ៖', NULL, '["ស្មើគ្នានឹងកម្ពស់ពិតជានិច្ច", "មិនសមាមាត្រទេ", "អាស្រ័យលើសម្ភារៈខ្សែ", "សមាមាត្រទៅនឹងកម្ពស់ពិតរវាងជាន់ (ទ្រឹស្តីបទតាលែសក្នុងលំហ)"]', 3, NULL, 3, 'mcq', 'តាមទ្រឹស្តីបទតាលែសក្នុងលំហ ប្លង់ជាន់ស្របគ្នាកាត់ខ្នាត់បានអង្កត់ត្រូវគ្នាសមាមាត្រគ្នា។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'pisa', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15734, 'ជើងតុកាហ្វេមួយមាន ៤ ជើងដែលមានប្រវែងស្មើគ្នា និងកែងនឹងផ្ទៃតុ។ ពេលដាក់លើកម្រាលរាបស្មើ ផ្ទៃតុតែងតែ ៖', NULL, '["មិនអាចស្របបានទេ", "កែងនឹងប្លង់កម្រាលឥដ្ឋ", "ទ្រេតមុំ ៤៥ ដឺក្រេ", "ស្របនឹងប្លង់កម្រាលឥដ្ឋ"]', 3, NULL, 3, 'mcq', 'អង្កត់ស្របគ្នានិងប៉ុនគ្នាខណ្ឌដោយប្លង់ស្របពីរ ធានាឱ្យផ្ទៃតុស្របនឹងកម្រាលឥដ្ឋ។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'pisa', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15735, 'ផ្លូវដែកភ្លោះរថភ្លើងរត់កាត់ស្ពានអាកាសត្រង់មួយ។ បន្ទាត់ផ្លូវដែកទាំងពីរ និងផ្ទៃទឹកទន្លេខាងក្រោម ៖', NULL, '["ផ្លូវដែកទាំងពីរកាត់គ្នាត្រង់ចំណុចមួយ", "ផ្លូវដែកទាំងពីរស្របគ្នា ហើយស្របនឹងផ្ទៃរាបនៃទឹកទន្លេ", "ផ្លូវដែកទាំងពីរជាបន្ទាត់ទ្វេរ", "ផ្លូវដែកទាំងពីរកែងនឹងផ្ទៃទឹក"]', 1, NULL, 3, 'mcq', 'ផ្លូវដែកទាំងពីររក្សាចម្ងាយថេរ (ស្របគ្នា) និងស្របនឹងផ្ទៃទឹករាបស្មើខាងក្រោម។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'pisa', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15736, 'ម៉ាស៊ីនស្កេន CT scan ថតស្រទាប់កាត់នៃរាងកាយជាបន្ទះស្ដើងៗស្របគ្នា។ បើចម្ងាយរវាងស្រទាប់នីមួយៗស្មើគ្នា \(2	ext{ mm}\) នោះគ្រប់ស្រទាប់កាត់ទាំងអស់ ៖', NULL, '["ជាប្លង់មិនអាចកំណត់បាន", "ជាប្លង់កែងគ្នា", "ជាប្លង់កាត់គ្នាតាមអ័ក្សកណ្តាល", "ជាប្លង់ស្របគ្នាដែលមានចម្ងាយស្មើៗគ្នា"]', 3, NULL, 3, 'mcq', 'ស្រទាប់ CT scan បង្កើតបានជាបណ្តុំប្លង់ស្របគ្នាក្នុងលំហ។', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'pisa', 1, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15737, 'ចូរឱ្យនិយមន័យនៃបន្ទាត់ពីរស្របគ្នាក្នុងលំហ និងសរសេរលក្ខខណ្ឌជាសញ្ញាណសំណុំ។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរនិយមន័យ ៖ បន្ទាត់ពីរស្របគ្នាក្នុងលំហ គឺជាបន្ទាត់ពីរដែលស្ថិតនៅក្នុងប្លង់តែមួយ ហើយគ្មានចំណុចរួម (១ ពិន្ទុ) (1 ពិន្ទុ)
បកស្រាយលក្ខខណ្ឌទី ១ ៖ បន្ទាត់ទាំងពីរត្រូវតែស្ថិតក្នុងប្លង់តែមួយ d1, d2 ⊂ (P) (១ ពិន្ទុ) (1 ពិន្ទុ)
បកស្រាយលក្ខខណ្ឌទី ២ ៖ បន្ទាត់ទាំងពីរគ្មានចំណុចរួមសោះ d1 ∩ d2 = ∅ (១ ពិន្ទុ) (1 ពិន្ទុ)
សរសេរសញ្ញាណសំណុំ ៖ d1 // d2 <=> { d1, d2 ⊂ (P) និង d1 ∩ d2 = ∅ } (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ បើគ្មានចំណុចរួមតែមិនក្នុងប្លង់តែមួយ វាជាបន្ទាត់ទ្វេរ មិនមែនបន្ទាត់ស្របទេ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'easy', 0, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15738, 'គេឱ្យបន្ទាត់ \(a \parallel b\) ដែល \(a \subset (P)\) និង \(b \subset (Q)\) ហើយ \((P) \cap (Q) = l\)។ ចូរបង្ហាញថា \(l \parallel a\) និង \(l \parallel b\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ទីតាំងបន្ទាត់ l ៖ បន្ទាត់ l ជាបន្ទាត់ប្រសព្វ នាំឱ្យ l ⊂ (P) និង l ⊂ (Q) (១ ពិន្ទុ) (1 ពិន្ទុ)
ពិនិត្យក្នុងប្លង់ (P) ៖ a ⊂ (P) និង l ⊂ (P) នាំឱ្យ a និង l អាចស្របគ្នា ឬកាត់គ្នា (១ ពិន្ទុ) (1 ពិន្ទុ)
ប្រើវិធីបដិសេធ ៖ ឧបមា l កាត់ a ត្រង់ M នាំឱ្យ M ∈ a និង M ∈ l ⊂ (Q) (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរកភាពផ្ទុយ ៖ ដោយ a // b ⊂ (Q) នាំឱ្យ a // (Q) មិនអាចកាត់ (Q) ត្រង់ M បានទេ (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ ដូច្នេះ l // a ហើយដោយភាពឆ្លង នាំឱ្យ l // b ដែរ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 0, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15739, 'គេឱ្យពីរ៉ាមីត \(S.ABCD\) មានបាត \(ABCD\) ជាការេ។ ប្លង់មួយកាត់តាម \(BC\) ប្រសព្វមុខ \((SAD)\) តាម \(IJ\) (\(I \in SA, J \in SD\))។ ចូរបញ្ជាក់ថា \(BCJI\) ជាចតុកោណព្នាយ។', NULL, '[]', 0, NULL, 5, 'writing', 'ទាញរក BC // AD ៖ ព្រោះ ABCD ជាការេ នាំឱ្យជ្រុងឈម BC // AD (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក BC // (SAD) ៖ ព្រោះ AD ⊂ (SAD) និង BC ⊄ (SAD) នាំឱ្យ BC // (SAD) (១ ពិន្ទុ) (1 ពិន្ទុ)
អនុវត្តលក្ខណៈប្លង់កាត់ ៖ ប្លង់ (BCJI) កាត់តាម BC // (SAD) ប្រសព្វ (SAD) តាម IJ (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក BC // IJ ៖ តាមលក្ខណៈទី ២ នៃបន្ទាត់ស្របនឹងប្លង់ នាំឱ្យ BC // IJ (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ ចតុកោណ BCJI មានជ្រុងឈម BC // IJ ដូច្នេះជាចតុកោណព្នាយ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 0, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15740, 'គេឱ្យប្លង់ពីរស្របគ្នា \((P) \parallel (Q)\) និងបន្ទាត់ពីរស្របគ្នា \(d_1 \parallel d_2\) កាត់ \((P)\) ត្រង់ \(A, B\) និងកាត់ \((Q)\) ត្រង់ \(C, D\)។ បង្ហាញថា \(AC = BD\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ប្លង់ (R) ៖ បន្ទាត់ស្រប d1 // d2 កំណត់បានប្លង់ (R) មួយ (១ ពិន្ទុ) (1 ពិន្ទុ)
រកបន្ទាត់ប្រសព្វ ៖ (R) ∩ (P) = AB និង (R) ∩ (Q) = CD (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក AB // CD ៖ តាមលក្ខណៈប្លង់ស្របកាត់ដោយប្លង់ទី ៣ នាំឱ្យ AB // CD (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក ABCD ជាប្រលេឡូក្រាម ៖ មាន AB // CD និង AC // BD នាំឱ្យជាប្រលេឡូក្រាម (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ ជ្រុងឈមនៃប្រលេឡូក្រាមស្មើគ្នា នាំឱ្យ AC = BD (១ ពិន្ទុ) (1 ពិន្ទុ)', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 0, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15741, 'ប្លង់ស្របគ្នាបី \((P) \parallel (Q) \parallel (R)\) កាត់ខ្នាត់ \(\Delta\) ត្រង់ \(A, B, C\) និងខ្នាត់ \(\Delta''\) ត្រង់ \(A'', B'', C''\)។ បើ \(AB = 4, BC = 6\) និង \(A''C'' = 15\) ចូរគណនា \(A''B''\) និង \(B''C''\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាប្រវែង AC ៖ AC = AB + BC = 4 + 6 = 10 (១ ពិន្ទុ) (1 ពិន្ទុ)
សរសេរផលធៀបតាលែស ៖ A''B'' / AB = B''C'' / BC = A''C'' / AC (១ ពិន្ទុ) (1 ពិន្ទុ)
គណនា A''B'' ៖ A''B'' = (AB x A''C'') / AC = (4 x 15) / 10 = 6 (១ ពិន្ទុ) (1 ពិន្ទុ)
គណនា B''C'' ៖ B''C'' = (BC x A''C'') / AC = (6 x 15) / 10 = 9 (១ ពិន្ទុ) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ A''B'' + B''C'' = 6 + 9 = 15 = A''C'' ត្រឹមត្រូវ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'medium', 0, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15742, 'គេឱ្យចតុមុខ \(ABCD\)។ បន្ទាត់ \(d\) កាត់តាម \(A\) ស្របនឹង \(BC\) ហើយបន្ទាត់ \(d''\) កាត់តាម \(D\) ស្របនឹង \(AB\)។ ចូរបង្ហាញថា \(d\) និង \(d''\) មិនស្ថិតក្នុងប្លង់តែមួយ។', NULL, '[]', 0, NULL, 5, 'writing', 'សន្មតផ្ទុយ ៖ ឧបមា d និង d'' ស្ថិតក្នុងប្លង់ (α) តែមួយ (១ ពិន្ទុ) (1 ពិន្ទុ)
កំណត់ប្លង់ (α) ៖ ដោយ A ∈ d និង D ∈ d'' នាំឱ្យបន្ទាត់ AD ⊂ (α) (១ ពិន្ទុ) (1 ពិន្ទុ)
