ទាញរកទីតាំង C ៖ (α) គឺជាប្លង់ (ABD)។ ដោយ d // BC និង d ⊂ (ABD) នាំឱ្យ C ∈ (ABD) (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋានភាពមិនអាច ៖ C ∈ (ABD) ផ្ទុយនឹងនិយមន័យចតុមុខ ABCD (៤ ចំណុចមិនក្នុងប្លង់តែមួយ) ដូច្នេះ d និង d'' ជាបន្ទាត់ទ្វេរ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'hard', 0, '11SC', 'បន្ទាត់និងប្លង់ស្របក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15743, 'ក្នុងចតុមុខ \(ABCD\) តាង \(I, J, K, L\) ជាចំណុចកណ្តាលរៀងគ្នានៃ \(AB, BC, CD, DA\)។ ចូរបង្ហាញថា \(IJKL\) ជាប្រលេឡូក្រាម។', NULL, '[]', 0, NULL, 5, 'writing', 'ពិនិត្យត្រីកោណ ABC ៖ I, J ជាចំណុចកណ្តាល AB, BC នាំឱ្យ IJ // AC និង IJ = AC/2 (១ ពិន្ទុ) (1 ពិន្ទុ)
