INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15747, 'ទូដាក់ឯកសារមួយមានថតចំនួន ៤ ជាន់រុញចេញចូលបាន។ ចូរពន្យល់ពីលក្ខណៈធរណីមាត្រដែលធ្វើឱ្យថតទូនីមួយៗមិនប៉ះទង្គិចគ្នាពេលរុញចេញចូលក្នុងពេលតែមួយ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ប្លង់ថតទូ ៖ បាតថតទូនីមួយៗជាប្លង់រាបស្មើ (P1), (P2), (P3), (P4) (១ ពិន្ទុ) (1 ពិន្ទុ)
